1	/**
2	 * RAINBOW master course — ONE continuous route through the washer world.
3	 *
4	 * Units: 1 unit ≈ 5 cm at Benny's scale (Benny body radius ≈ 0.8). +Y is up (absolute altitude).
5	 * The route starts inside Drum A (scene 01/02), drains through a chute into the whirlpool basin (03),
6	 * drops down the five-arrow slide (04), winds through the perforated current tube (05), crests the
7	 * rinse arch (06), winds through the washer tube and then PLUNGES ~62 units straight down (07) before
8	 * the bottom of that same tube flares into the Final Spin Chamber inlet (08). 08–10 stay in that same
9	 * chamber; the route ends under the purple towel on the platform, where the 11 cinematic plays.
10	 *
11	 * Every stage is a range of arc-length `s` on a single centripetal Catmull-Rom spline, so position
12	 * and tangent are continuous by construction; `validateContinuity()` measures it anyway.
13	 */
14	import * as THREE from 'three';
15	
16	export type StageId = '01' | '02' | '03' | '04' | '05' | '06' | '07' | '08' | '09' | '10' | '11';
17	export type TubeKind = 'none' | 'chute' | 'gold' | 'perf';
18	
19	export interface StageDef {
20	  id: StageId;
21	  title: string;
22	  /** arc-length range on the course */
23	  s0: number;
24	  s1: number;
25	  /** water ribbon width (units) */
26	  width: number;
27	  /** enclosing tube radius (0 = open environment such as a drum/basin/chamber) */
28	  tube: number;
29	  tubeKind: TubeKind;
30	  /** auto-propulsion speed (units / s) */
31	  speed: number;
32	  /** coin counter shown in the locked reference screenshot of this stage */
33	  refCoins: number;
34	  interactive: boolean;
35	  /** banking strength multiplier */
36	  bank: number;
37	}
38	
39	export interface CourseSample {
40	  s: number;
41	  pos: THREE.Vector3;
42	  tan: THREE.Vector3;
43	  up: THREE.Vector3;
44	  right: THREE.Vector3;
45	}
46	
47	export const STAGE_TITLES: Record<StageId, string> = {
48	  '01': 'INSIDE THE WASHING MACHINE',
49	  '02': 'WHIRLPOOL TUMBLE',
50	  '03': 'WHIRLPOOL TWIRL',
51	  '04': 'THROUGH THE FIVE ARROWS',
52	  '05': 'FLOW INTO THE CURRENT',
53	  '06': 'CREST THE RINSE ARCH',
54	  '07': 'DIVE THE WASHER TUBE',
55	  '08': 'FINAL SPIN CHAMBER',
56	  '09': 'RIDE THE FINAL WAVE',
57	  '10': 'SLIDE INTO HIDING',
58	  '11': 'SAFELY HOME',
59	};
60	
61	/** Fixed world anchors shared by environment builders (absolute coordinates). */
62	export const WORLD = {
63	  drumA: { center: new THREE.Vector3(0, 0, 0), radius: 5, zBack: -6.5, zDoor: 3.5, doorRadius: 3.2, waterY: -2.5 },
64	  basin: { center: new THREE.Vector3(2, -16, -19), rimRadius: 11.5, rimY: -10.6, drainRadius: 2.6, drainY: -20.2 },
65	  /** Final Spin Chamber (08–11): drum with axis along Z, door at the far (-Z) end */
66	  chamber: { center: new THREE.Vector3(12, -101.1, 0), radius: 13.5, zBack: -280, zDoor: -332, floorY: -113.6, doorRadius: 6.2 },
67	  platform: { center: new THREE.Vector3(12, -110.6, -322.5), radius: 6.2, topY: -110.6 },
68	  plunge: { topY: -52, bottomY: -113.6 },
69	};
70	
71	/** funnel surface height of the whirlpool basin as a function of radius from its axis */
72	export function funnelY(r: number): number {
73	  const b = WORLD.basin;
74	  const t = THREE.MathUtils.clamp((r - b.drainRadius * 0.6) / (b.rimRadius - b.drainRadius * 0.6), 0, 1);
75	  return b.drainY + (b.rimY - b.drainY) * Math.pow(t, 0.72);
76	}
77	
78	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
79	const smooth = (a: number, b: number, x: number) => {
80	  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
81	  return t * t * (3 - 2 * t);
82	};
83	
84	interface RouteData {
85	  points: THREE.Vector3[];
86	  marks: Record<string, number>;
87	}
88	
89	/** Generates the dense control polyline of the route (absolute coordinates). */
90	function buildRoute(): RouteData {
